function load(id){const row=receipt.results.find(x=>x.id===id),root=`${base}/${id}/current-libs/${id}/${row.version}`,sha=x=>crypto.createHash('sha256').update(x).digest('hex'),manifest=fs.readFileSync(root+'/lib.json'),core=fs.readFileSync(root+'/artifact.wasm');assert.equal(sha(manifest),row.manifest_sha256);assert.equal(sha(core),row.artifact_sha256);return new CoreCaller(new WebAssembly.Module(core),JSON.parse(fs.readFileSync(root+'/core-abi.json')))}
const dtype=enumeration(['boolean','int64','uint64','float64','utf8','binary']),field=record({name:string,data_type:dtype,nullable:bool}),column=variant(Object.fromEntries([['boolean',bool],['int64',i64],['uint64',u64],['float64',f64],['utf8',string],['binary',list(u8)]].map(([n,t])=>[n,list(option(t))]))),batch=record({rows:u32,fields:list(field),columns:list(column)}),coreErrors=['column-count-mismatch','row-count-mismatch','type-mismatch','nullability-violation','empty-field-name','duplicate-field-name','index-out-of-bounds','invalid-layout'],profileErrors=['invalid-batch','column-out-of-bounds','duplicate-column','overflow','compute-failure'];
